import sys
import json
import os
from datetime import datetime

class ContactCache:
    def __init__(self):
        self.contacts = {}
        self.log_file = "contacts.log"
        self.bin_file = "contacts.bin"
        self.load_startup_data()

    def load_startup_data(self):
        try:
            if os.path.exists(self.bin_file):
                with open(self.bin_file, 'r') as f:
                    self.contacts = json.load(f)
        except Exception:
            self.log_error("startup load failed")

    def log_error(self, message):
        timestamp = datetime.utcnow().isoformat()
        with open(self.log_file, 'a') as f:
            f.write(f"{timestamp} {message}\n")

    def process_command(self, line):
        line = line.strip()
        if not line:
            return

        parts = line.split()
        if not parts:
            return

        command = parts[0].lower()
        if command == "quit":
            return True
        elif command == "list":
            self.print_contacts()
        elif command == "add":
            if len(parts) != 3:
                self.log_error(line)
                return False
            name, phone = parts[1], parts[2]
            self.contacts[name] = phone
            self.save_contacts()
        else:
            self.log_error(line)

    def print_contacts(self):
        sorted_contacts = sorted(self.contacts.items())
        for name, phone in sorted_contacts:
            print(f"{name}: {phone}")

    def save_contacts(self):
        with open(self.bin_file, 'w') as f:
            json.dump(self.contacts, f)

def main():
    cache = ContactCache()
    for line in sys.stdin:
        if cache.process_command(line):
            break

if __name__ == "__main__":
    main()

