import sys
import json
from datetime import datetime, timezone
import os

def load_contacts():
    if os.path.exists('contacts.bin'):
        with open('contacts.bin', 'r') as f:
            return json.load(f)
    return {}

def save_contacts(contacts):
    with open('contacts.bin', 'w') as f:
        json.dump(contacts, f)

def log_entry(message):
    timestamp = datetime.now(timezone.utc).isoformat()
    with open('contacts.log', 'a') as f:
        f.write(f"{timestamp} {message}\n")

def process_command(command_line):
    parts = command_line.split()
    if not parts:
        return False
    cmd = parts[0]
    if cmd == 'add':
        if len(parts) != 3:
            log_entry(command_line.rstrip('\n'))
            return False
        name, phone = parts[1], parts[2]
        return name, phone
    elif cmd == 'list':
        return None
    elif cmd == 'quit':
        return None
    else:
        log_entry(command_line.rstrip('\n'))
        return False

def main():
    contacts = load_contacts()
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.rstrip('\n')
        if line == 'quit':
            break
        if not process_command(line):
            continue
        if line == 'list':
            for name in sorted(contacts.keys()):
                print(f"{name}: {contacts[name]}")
        else:
            name, phone = process_command(line)
            if name is not None:
                contacts[name] = phone
                save_contacts(contacts)

if __name__ == "__main__":
    main()

